def most_frequent_char(txt):
    cfg = {}
    prev_idx = {}
    max_cnt = -1
    res = ''

    for idx, char_raw in enumerate(txt):
        curr_char = char_raw.lower()
        if curr_char == ' ':
            continue

        if curr_char not in cfg:
            cfg[curr_char] = 0
            prev_idx[curr_char] = idx

        cfg[curr_char] += 1
        cnt_curr = cfg[curr_char]

        if cnt_curr > max_cnt:
            max_cnt = cnt_curr
            res = curr_char
        elif cnt_curr == max_cnt:
            if prev_idx[curr_char] < prev_idx[res]:
                res = curr_char
    return res

