def is_anagram(s1, s2):
    def _normalize(s):
        tmp = "".join(list(filter(lambda char: char != ' ', s))).lower()
        return sorted(list(tmp))

    norm_s1 = _normalize(s1)
    norm_s2 = _normalize(s2)

    if len(norm_s1) != len(norm_s2):
        return False

    for idx in range(len(norm_s1)):
        if norm_s1[idx] != norm_s2[idx]:
            return False
    return True

def is_anagram_optimized(s1, s2):
    cfg = {}
    for char in s1.lower():
        if char != ' ':
            cfg[char] = cfg.get(char, 0) + 1

    for char in s2.lower():
        if char != ' ':
            cfg[char] = cfg.get(char, 0) - 1

    for val in cfg.values():
        if val != 0:
            return False
    return True

