def has_conflict(sched, new_event_start, new_event_end):
    for idx in range(len(sched)):
        curr_event = sched[idx]
        curr_start, curr_end = curr_event
        if new_event_start < curr_end and new_event_end > curr_start:
            return True
    return False

def add_event_if_no_conflict(sched, start_val, end_val):
    if not has_conflict(sched, start_val, end_val):
        sched.append((start_val, end_val))
        return True
    return False

def get_total_duration(sched):
    total_dur = 0
    for elem in sched:
