def has_conflict(schedule, new_event_start, new_event_end):
    for index in range(len(schedule)):
        current_event = schedule[index]
        current_start, current_end = current_event
        if new_event_start < current_end and new_event_end > current_start:
            return True
    return False

def add_event_if_no_conflict(schedule, start_value, end_value):
    if not has_conflict(schedule, start_value, end_value):
        schedule.append((start_value, end_value))
        return True
    return False

def get_total_duration(schedule):
