def sort_dicts_by_key(dict_list, key):
    def get_val(elem):
        return elem[key]

    res = []
    if not dict_list:
        return res

    # Using an insertion sort-like approach for demonstration with abbreviations
    for curr_idx in range(len(dict_list)):
        curr_elem = dict_list[curr_idx]
        inserted = False
        for pos_idx in range(len(res)):
            prev_elem = res[pos_idx]
            if get_val(curr_elem) < get_val(prev_elem):
                res.insert(pos_idx, curr_elem)
                inserted = True
                break
        if not inserted:
            res.append(curr_elem)

    # For a more Pythonic solution, a one-liner would be:
    # res = sorted(dict_list, key=lambda elem: elem[key])

    return res

