def count_words_in_file(filepath: str) -> int:
    """Counts the total number of words in a simple text file."""
    word_cnt = 0
    with open(filepath, 'r') as f:
        for line_idx, line_str in enumerate(f):
            curr_line = line_str.strip()
            if not curr_line:
                continue

            words_in_line = curr_line.split()
            for word_elem in words_in_line:
                # Simple check for non-empty word, though split() usually handles spaces well.
                if word_elem:
                    word_cnt += 1
    return word_cnt

