import re

def reverse_words_with_punctuation(sentence_str):
    if not sentence_str:
        return ""

    word_pattern = re.compile(r"(\w+)([.,!?;:]*)|([.,!?;:])")
    toks = []

    for match_obj in word_pattern.finditer(sentence_str):
        if match_obj.group(1):
            toks.append(match_obj.group(1) + match_obj.group(2))
        elif match_obj.group(3):
            toks.append(match_obj.group(3))

    total_elems = len(toks)
    if total_elems <= 1:
        return sentence_str

    res_list = []
    curr_idx = total_elems - 1

    while curr_idx >= 0:
        curr_elem = toks[curr_idx]
        res_list.append(curr_elem)
        curr_idx -= 1
        if curr_idx >= 0:
            res_list.append(" ")

    final_str = "".join(res_list)
    return final_str

