def is_valid_isbn10(isbn_str):
    if not isinstance(isbn_str, str) or len(isbn_str) != 10:
        return False

    curr_sum = 0
    cnt_digits = 0
    final_digit_val = 0

    for idx, elem in enumerate(isbn_str):
        curr_pos = idx + 1
        if idx < 9:
            if not ('0' <= elem <= '9'):
                return False
            curr_val = int(elem)
            curr_sum += curr_val * curr_pos
            cnt_digits += 1
        else: # Last digit
            if '0' <= elem <= '9':
                final_digit_val = int(elem)
            elif elem == 'X':
                final_digit_val = 10
            else:
                return False
            curr_sum += final_digit_val * curr_pos

    if cnt_digits != 9: # Ensure 9 digits processed before the last one
        return False

    return curr_sum % 11 == 0

