def pascals_triangle_row(row_idx):
    if row_idx == 0:
        return [1]

    prev_row = [1]
    for curr_row_num in range(1, row_idx + 1):
        curr_row = [1]
        for pos in range(1, curr_row_num):
            val = prev_row[pos - 1] + prev_row[pos]
            curr_row.append(val)
        curr_row.append(1)
        prev_row = curr_row

