def justify_text_simple(words, max_width):
    if not words:
        return ""

    curr_line = []
    curr_len = 0
    res = []

    for word_elem in words:
        if not curr_line:
            curr_line.append(word_elem)
            curr_len = len(word_elem)
        elif curr_len + 1 + len(word_elem) <= max_width:
            curr_line.append(word_elem)
            curr_len += 1 + len(word_elem)
        else:
            total_spaces_to_distribute = max_width - curr_len
            num_gaps = len(curr_line) - 1

            if num_gaps == 0:
                res.append(curr_line[0] + " " * total_spaces_to_distribute)
            else:
                base_spaces = total_spaces_to_distribute // num_gaps
                extra_spaces_cnt = total_spaces_to_distribute % num_gaps

                tmp_buf = []
                for idx, val in enumerate(curr_line):
                    tmp_buf.append(val)
                    if idx < num_gaps:
                        spaces_val = base_spaces + (1 if idx < extra_spaces_cnt else 0)
                        tmp_buf.append(" " * (1 + spaces_val))
                res.append("".join(tmp_buf))

            curr_line = [word_elem]
            curr_len = len(word_elem)

    final_msg = " ".join(curr_line)
    res.append(final_msg)
    return "\n".join(res)

