def caesar_encrypt(txt_in, shft_amt):
    res_buf = []

    for curr_char in txt_in:
        curr_ascii_val = ord(curr_char)

        if 'a' <= curr_char <= 'z':
            base_val = ord('a')
            shifted_val = (curr_ascii_val - base_val + shft_amt) % 26 + base_val
            res_buf.append(chr(shifted_val))
        elif 'A' <= curr_char <= 'Z':
            base_val = ord('A')
            shifted_val = (curr_ascii_val - base_val + shft_amt) % 26 + base_val
            res_buf.append(chr(shifted_val))
        else:
            res_buf.append(curr_char)

    final_str_val = "".join(res_buf)
    return final_str_val

