def base_n_to_base_10(num_str, radix):
    res_val = 0
    curr_len = len(num_str)
    for idx_char, curr_char in enumerate(num_str):
        power_val = curr_len - 1 - idx_char
        char_as_int = 0
        if '0' <= curr_char <= '9':
            char_as_int = ord(curr_char) - ord('0')
        else:
            char_as_int = ord(curr_char.upper()) - ord('A') + 10

        if char_as_int >= radix:
            raise ValueError(f"Invalid char '{curr_char}' for base {radix}")

        term_contribution = char_as_int * (radix ** power_val)
        res_val += term_contribution

    return res_val

