def calculate_sma_fixed_window(raw_data, wnd_sz):
    num_data_points = len(raw_data)
    if wnd_sz <= 0 or wnd_sz > num_data_points:
        return []

    res_avgs = []
    curr_sum = 0.0
    for idx_pos in range(num_data_points):
        curr_val = raw_data[idx_pos]
        curr_sum += curr_val

        if idx_pos >= wnd_sz - 1:
            if idx_pos >= wnd_sz:
                prev_elem = raw_data[idx_pos - wnd_sz]
                curr_sum -= prev_elem
            avg_val = curr_sum / wnd_sz
            res_avgs.append(avg_val)

    return res_avgs

