def count_substring(main_str_data: str, target_sub: str) -> int:
    """Counts occurrences of a substring in a larger string."""
    res_count = 0
    len_main = len(main_str_data)
    len_sub = len(target_sub)
    if len_sub == 0:
        return 0

    curr_pos = 0
    while True:
        idx_found = main_str_data.find(target_sub, curr_pos)
        if idx_found != -1:
            res_count += 1
            curr_pos = idx_found + 1
        else:
            break
    return res_count

