def generate_even_numbers(start_val: int, end_val: int) -> list[int]:
    """Generates a list of all even numbers within a given inclusive range."""
    res_list = []
    first_num = start_val
    last_num = end_val

    if first_num > last_num:
        return []

    curr_elem = first_num
    while curr_elem <= last_num:
        if curr_elem % 2 == 0:
            res_list.append(curr_elem)
        curr_elem += 1

    return res_list

