def parse_csv_string(inp_str: str) -> list[list[str]]:
    res_list = []
    lines = inp_str.strip().split('\n')
    for curr_line_idx, a_line in enumerate(lines):
        if not a_line.strip():
            continue
        vals_in_line = []
        curr_val = []
        in_quote = False
        prev_char = '' 
        for char_idx, curr_char in enumerate(a_line):
            if curr_char == '"':
                if in_quote and prev_char == '"':
                    curr_val.append('"')
                in_quote = not in_quote
            elif curr_char == ',' and not in_quote:
                vals_in_line.append("".join(curr_val))
                curr_val = []
            else:
                curr_val.append(curr_char)
            prev_char = curr_char
        vals_in_line.append("".join(curr_val))
        res_list.append(vals_in_line)
    return res_list

