def has_substring_case_insensitive(main_str_val: str, sub_str_val: str) -> bool:
    main_len = len(main_str_val)
    sub_len = len(sub_str_val)
    if sub_len == 0:
        return True

    if main_len < sub_len:
        return False

    norm_main_str = main_str_val.lower()
    norm_sub_str = sub_str_val.lower()

    for idx_main in range(main_len - sub_len + 1):
        curr_slice = norm_main_str[idx_main : idx_main + sub_len]
        if curr_slice == norm_sub_str:
            return True

    return False

